/**
 * Component: Animated Text Rotator | Smooth Tailwindcss Text Transition Effects
 * Author: @homayunmmdy (https://tailwindflex.com/@homayunmmdy)
 * Source: https://tailwindflex.com/@homayunmmdy/animated-text-rotator-smooth-css-text-transition-effects
 * Attribution: Créé par @homayunmmdy sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function AnimatedTextRotatorSmoothCssTextTransitionEffects() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<body 
  class="bg-white dark:bg-gray-800 flex justify-center items-center w-screen h-screen p-5"
>
  <div class="text-rotate-container relative h-32 flex items-center justify-center w-full max-w-4xl">
    <div class="text-item text-5xl font-bold text-black dark:text-white">
      Welcome to Our Platform
    </div>
    <div class="text-item text-5xl font-bold text-blue-400">
      Build Amazing Things
    </div>
    <div class="text-item text-5xl font-bold text-purple-400">
      Transform Your Ideas
    </div>
    <div class="text-item text-5xl font-bold text-green-400">
      Create Without Limits
    </div>
    <div class="text-item text-5xl font-bold text-orange-400">
      Innovate Every Day
    </div>
  </div>


</body>

<style>
@keyframes textRotate {
  0%, 5% {
    opacity: 0;
    transform: translateY(20px);
  }
  10%, 25% {
    opacity: 1;
    transform: translateY(0);
  }
  30%, 100% {
    opacity: 0;
    transform: translateY(-20px);
  }
}

.text-item {
  animation: textRotate 20s infinite linear;
  position: absolute;
  width: 100%;
  text-align: center;
  opacity: 0;
}

.text-item:nth-child(1) { animation-delay: 0s; }
.text-item:nth-child(2) { animation-delay: 4s; }
.text-item:nth-child(3) { animation-delay: 8s; }
.text-item:nth-child(4) { animation-delay: 12s; }
.text-item:nth-child(5) { animation-delay: 16s; }

.text-rotate-container:hover .text-item {
  animation-play-state: paused;
}
</style>" }} />
  );
}
